import{_ as t,o as i,c as s,ae as o}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Session Replay UI, Retention, Export, and Tests","description":"","frontmatter":{"work_package_id":"WP04","title":"Session Replay UI, Retention, Export, and Tests","lane":"done","dependencies":["WP03"],"base_branch":"024-audit-logging-and-session-replay-WP03","base_commit":"53e54ede247a335018e5db1cd28126295031549f","created_at":"2026-03-01T13:36:08.528223+00:00","subtasks":["T014","T015","T016","T017","T018","T019","T020","T021"],"phase":"Phase 3 - Replay and Compliance","assignee":"","agent":"claude-haiku","shell_pid":"82027","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/024-audit-logging-and-session-replay/tasks/WP04-session-replay-retention-export.md","filePath":"specs/024-audit-logging-and-session-replay/tasks/WP04-session-replay-retention-export.md"}'),l={name:"specs/024-audit-logging-and-session-replay/tasks/WP04-session-replay-retention-export.md"};function a(r,e,n,d,p,c){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="work-package-prompt-wp04-session-replay-ui-retention-export-and-tests" tabindex="-1">Work Package Prompt: WP04 - Session Replay UI, Retention, Export, and Tests <a class="header-anchor" href="#work-package-prompt-wp04-session-replay-ui-retention-export-and-tests" aria-label="Permalink to &quot;Work Package Prompt: WP04 - Session Replay UI, Retention, Export, and Tests&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Capture session state snapshots for replay reconstruction.</li><li>Deliver a session replay engine with time-indexed random access.</li><li>Deliver a replay UI with play/pause, speed control, and time-scrub.</li><li>Implement retention policies with automated purge and deletion proofs.</li><li>Implement JSON export with redaction hooks.</li><li>Comprehensive chaos, replay, and compliance tests.</li></ul><p>Success criteria:</p><ul><li>Session replay reconstructs terminal output for 95%+ of test sessions.</li><li>Time-scrub to a specific timestamp renders terminal state within 200ms.</li><li>Retention purge deletes only expired, non-held events with valid deletion proofs.</li><li>Export produces redacted JSON bundles with zero leaked sensitive values.</li><li>Zero event loss in 24-hour soak test.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/spec.md</code></li><li>WP01-03 output: AuditEvent schema, sink, ring buffer, SQLite store, ledger with filters.</li></ul><p>Constraints:</p><ul><li>Replay scrub-to-render &lt; 200ms (NFR-024-003).</li><li>Retention must produce deletion audit proofs.</li><li>Export without redaction rules must be blocked.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP04</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t014-implement-session-state-snapshot-capture" tabindex="-1">Subtask T014 - Implement session state snapshot capture <a class="header-anchor" href="#subtask-t014-implement-session-state-snapshot-capture" aria-label="Permalink to &quot;Subtask T014 - Implement session state snapshot capture&quot;">​</a></h3><ul><li>Purpose: Capture periodic snapshots of terminal state for efficient replay reconstruction.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/snapshot.ts</code>.</li><li>Define <code>SessionSnapshot</code> interface: <ul><li><code>id</code>: unique string (UUID)</li><li><code>sessionId</code>: string</li><li><code>timestamp</code>: ISO 8601</li><li><code>terminalBuffer</code>: string (full terminal buffer contents at capture time)</li><li><code>cursorPosition</code>: <code>{ row: number, col: number }</code></li><li><code>dimensions</code>: <code>{ rows: number, cols: number }</code></li><li><code>scrollbackPosition</code>: number</li></ul></li><li>Implement <code>SnapshotCapture</code> class: <ul><li>Accept a session reference and snapshot interval (default 30 seconds).</li><li>Start a timer that captures the current terminal state at each interval.</li><li>On capture: read the terminal buffer, cursor position, and dimensions from the session&#39;s terminal.</li><li>Create a <code>SessionSnapshot</code> object and persist it via the audit sink.</li><li>Stop capturing when the session ends.</li></ul></li><li>Implement <code>captureNow(sessionId)</code> for on-demand snapshot capture (e.g., before critical operations).</li><li>Store snapshots in SQLite alongside audit events (separate table <code>session_snapshots</code>).</li><li>Optimize: diff-based compression between consecutive snapshots if buffer is large.</li><li>Handle edge cases: terminal not yet ready (skip capture), session ended mid-capture (discard).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/snapshot.ts</code></li></ul></li><li>Acceptance: <ul><li>Snapshots captured at configurable intervals.</li><li>On-demand capture available.</li><li>Snapshots persisted to SQLite.</li><li>Edge cases handled gracefully.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t015-implement-session-replay-engine" tabindex="-1">Subtask T015 - Implement session replay engine <a class="header-anchor" href="#subtask-t015-implement-session-replay-engine" aria-label="Permalink to &quot;Subtask T015 - Implement session replay engine&quot;">​</a></h3><ul><li>Purpose: Reconstruct terminal output from snapshots and events for historical session review.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/replay.ts</code>.</li><li>Define <code>ReplayStream</code> interface: <ul><li><code>sessionId</code>: string</li><li><code>snapshots</code>: ordered array of <code>SessionSnapshot</code></li><li><code>events</code>: ordered array of <code>AuditEvent</code> for the session</li><li><code>startTime</code>: Date</li><li><code>endTime</code>: Date</li><li><code>duration</code>: number (milliseconds)</li></ul></li><li>Implement <code>ReplayEngine</code> class: <ul><li><code>loadSession(sessionId): ReplayStream</code>: load all snapshots and events for a session.</li><li><code>getStateAtTime(stream: ReplayStream, timestamp: Date): SessionSnapshot</code>: find the nearest snapshot before the timestamp, then apply events between the snapshot and timestamp to reconstruct the terminal state.</li><li><code>getTimeline(stream: ReplayStream): TimelineEntry[]</code>: return an array of significant moments (command executions, errors, approvals) for the time-scrub UI.</li></ul></li><li>Handle missing snapshots: degrade to event-only reconstruction by replaying events from the session start. Log a warning about reduced fidelity.</li><li>Handle corrupted snapshots: skip and fall back to the previous valid snapshot.</li><li>Optimize: cache recently reconstructed states for smooth scrubbing.</li><li>Verify reconstruction accuracy by comparing replay output to actual terminal output for test sessions.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/replay.ts</code></li></ul></li><li>Acceptance: <ul><li>Session replay reconstructs terminal state from snapshots + events.</li><li>Time-indexed random access works (scrub to any timestamp).</li><li>Missing/corrupted snapshots handled gracefully.</li><li>State-at-time renders within 200ms.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t016-implement-session-replay-ui" tabindex="-1">Subtask T016 - Implement session replay UI <a class="header-anchor" href="#subtask-t016-implement-session-replay-ui" aria-label="Permalink to &quot;Subtask T016 - Implement session replay UI&quot;">​</a></h3><ul><li>Purpose: Provide an interactive UI for operators to review historical terminal sessions.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/session-replay.ts</code>.</li><li>UI layout: <ul><li>Terminal render area showing the reconstructed terminal state.</li><li>Time-scrub slider spanning the session duration with tick marks at snapshot intervals.</li><li>Play/pause button for automated playback.</li><li>Speed controls: 0.5x, 1x, 2x, 4x playback speed.</li><li>Timeline bar showing significant events (commands, errors, approvals) as markers.</li><li>Session metadata: session ID, workspace, lane, start/end times, duration.</li></ul></li><li>Connect the UI to the replay engine: <ul><li>On scrub: call <code>getStateAtTime()</code> and render the result in the terminal area.</li><li>On play: advance the scrub position at the selected speed, updating the terminal render.</li><li>On pause: stop advancement.</li><li>On timeline marker click: jump to that event&#39;s timestamp.</li></ul></li><li>Render terminal state using a terminal emulator component (reuse or adapt the existing ghostty/rio renderer).</li><li>Handle long sessions (&gt; 1 hour) efficiently: lazy-load events and snapshots as the scrub moves.</li><li>Show loading indicator when reconstructing state at a new position.</li><li>Handle sessions with no replay data: show &quot;No replay data available&quot; message.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/session-replay.ts</code></li></ul></li><li>Acceptance: <ul><li>Replay UI renders terminal state at any timestamp.</li><li>Time-scrub, play/pause, and speed controls work.</li><li>Timeline markers for significant events.</li><li>Long sessions handled without memory issues.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t017-implement-retention-policy-model" tabindex="-1">Subtask T017 - Implement retention policy model <a class="header-anchor" href="#subtask-t017-implement-retention-policy-model" aria-label="Permalink to &quot;Subtask T017 - Implement retention policy model&quot;">​</a></h3><ul><li>Purpose: Define per-workspace retention policies that control how long audit events are kept.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/retention.ts</code>.</li><li>Define <code>RetentionPolicy</code> interface: <ul><li><code>workspaceId</code>: string</li><li><code>ttlDays</code>: number (default 30)</li><li><code>legalHold</code>: boolean (default false; if true, override TTL — events are never purged)</li><li><code>purgeSchedule</code>: cron expression or interval string (default: daily)</li></ul></li><li>Implement <code>RetentionPolicyStore</code>: <ul><li>Load/save policies from SQLite (separate table <code>retention_policies</code>).</li><li><code>getPolicy(workspaceId)</code>: return policy or default.</li><li><code>setPolicy(workspaceId, policy)</code>: create or update.</li></ul></li><li>Define <code>DeletionProof</code> interface: <ul><li><code>proofId</code>: unique string</li><li><code>workspaceId</code>: string</li><li><code>purgedEventCount</code>: number</li><li><code>oldestEventTimestamp</code>, <code>newestEventTimestamp</code>: ISO 8601</li><li><code>hashChain</code>: string (hash of all purged event IDs in order)</li><li><code>purgedAt</code>: ISO 8601</li></ul></li><li>The hash chain provides verifiable proof that specific events were purged (not selectively deleted).</li><li>Export types for use by the purge engine and UI.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/retention.ts</code></li></ul></li><li>Acceptance: <ul><li>Retention policies configurable per workspace.</li><li>Legal hold overrides TTL.</li><li>Deletion proof schema defined.</li><li>Default 30-day TTL.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t018-implement-automated-retention-purge-with-deletion-proofs" tabindex="-1">Subtask T018 - Implement automated retention purge with deletion proofs <a class="header-anchor" href="#subtask-t018-implement-automated-retention-purge-with-deletion-proofs" aria-label="Permalink to &quot;Subtask T018 - Implement automated retention purge with deletion proofs&quot;">​</a></h3><ul><li>Purpose: Automatically purge expired events while producing verifiable deletion proofs.</li><li>Steps: <ol><li>In <code>retention.ts</code> or a new <code>purge.ts</code>, implement <code>RetentionPurger</code> class: <ul><li><code>runPurge(workspaceId?)</code>: for each workspace, check the retention policy, find events older than TTL.</li><li>Skip workspaces with <code>legalHold: true</code>.</li><li>For expired events: a. Compute the hash chain: hash each event ID in order, chain the hashes. b. Record event metadata (count, time range) for the deletion proof. c. Delete the events from SQLite. d. Delete associated snapshots. e. Create and persist the <code>DeletionProof</code>.</li><li>Write an audit event documenting the purge itself (meta-audit).</li></ul></li><li>Run purge on a configurable schedule (timer-based, default daily).</li><li>Ensure purge is atomic per workspace: either all expired events are purged or none (transaction).</li><li>Handle partial failures: if deletion fails, do not create a deletion proof.</li><li>Add a <code>bun run audit:purge</code> command for manual purge triggering.</li><li>Test: create events older than TTL, run purge, verify deletion and valid proof.</li><li>Test: create events with legal hold, run purge, verify events preserved.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/retention.ts</code> (or new purge.ts)</li></ul></li><li>Acceptance: <ul><li>Expired events purged with valid deletion proofs.</li><li>Legal hold events preserved.</li><li>Purge is atomic per workspace.</li><li>Meta-audit event records the purge.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t019-implement-json-export-with-redaction-hooks" tabindex="-1">Subtask T019 - Implement JSON export with redaction hooks <a class="header-anchor" href="#subtask-t019-implement-json-export-with-redaction-hooks" aria-label="Permalink to &quot;Subtask T019 - Implement JSON export with redaction hooks&quot;">​</a></h3><ul><li>Purpose: Produce exportable audit bundles with sensitive values redacted per spec 028 rules.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/export.ts</code>.</li><li>Implement <code>AuditExporter</code> class: <ul><li><code>exportWorkspace(workspaceId, filter?): ExportBundle</code>: query events matching the filter, apply redaction, produce JSON bundle.</li><li><code>exportSession(sessionId): ExportBundle</code>: export all events and snapshots for a session.</li></ul></li><li>Define <code>ExportBundle</code> interface: <code>{ metadata: ExportMetadata, events: AuditEvent[], snapshots?: SessionSnapshot[] }</code>.</li><li>Implement redaction hooks: <ul><li>Define <code>RedactionRule</code> interface: <code>{ pattern: RegExp, replacement: string, description: string }</code>.</li><li>Apply redaction rules to all string fields in events and snapshots before export.</li><li>If no redaction rules are configured (spec 028 not yet implemented), block the export with a clear error: &quot;Redaction rules required before export is permitted.&quot;</li></ul></li><li>Add placeholder redaction rules for common sensitive patterns: API keys, passwords, tokens, email addresses.</li><li>Validate export completeness: every event in the query result must appear in the bundle.</li><li>Add export metadata: workspace ID, export timestamp, event count, redaction rules applied.</li><li>Add <code>bun run audit:export</code> command.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/export.ts</code></li></ul></li><li>Acceptance: <ul><li>Export produces valid JSON bundles.</li><li>Redaction hooks applied to all string fields.</li><li>Export blocked without redaction rules.</li><li>Export metadata complete.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t020-chaos-retention-and-export-tests" tabindex="-1">Subtask T020 - Chaos, retention, and export tests <a class="header-anchor" href="#subtask-t020-chaos-retention-and-export-tests" aria-label="Permalink to &quot;Subtask T020 - Chaos, retention, and export tests&quot;">​</a></h3><ul><li>Purpose: Validate the complete audit system under stress with chaos scenarios, retention compliance, and export redaction.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/compliance.test.ts</code>.</li><li>Chaos test: write events for 1 hour (simulated), simulate crashes at random intervals, verify zero event loss by comparing written vs persisted counts.</li><li>Retention test: create events with known timestamps, configure 7-day TTL, advance time simulation, run purge, verify only expired events deleted.</li><li>Retention test: create events, set legal hold, run purge, verify events preserved despite TTL expiry.</li><li>Retention test: verify deletion proofs are valid (recompute hash chain from purged event IDs and compare).</li><li>Export test: create 1000 events with simulated sensitive data, export with redaction, verify zero sensitive values in output (scan for known patterns).</li><li>Export test: attempt export without redaction rules, verify export is blocked.</li><li>Export test: verify export bundle contains all queried events (completeness check).</li><li>Soak test: write 100k events over simulated 24 hours, verify audit completeness (every event has a corresponding record).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/compliance.test.ts</code></li></ul></li><li>Acceptance: <ul><li>Zero event loss in chaos scenarios.</li><li>Retention purge correct (expired only, legal hold respected).</li><li>Deletion proofs valid.</li><li>Export redaction verified across 1000 bundles.</li></ul></li><li>Parallel: Yes (after T014-T019 are functional).</li></ul><h3 id="subtask-t021-replay-fidelity-tests" tabindex="-1">Subtask T021 - Replay fidelity tests <a class="header-anchor" href="#subtask-t021-replay-fidelity-tests" aria-label="Permalink to &quot;Subtask T021 - Replay fidelity tests&quot;">​</a></h3><ul><li>Purpose: Validate that session replay accurately reconstructs terminal output.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/replay-fidelity.test.ts</code>.</li><li>Record a test session: execute a series of known commands with known output, capturing snapshots at 30-second intervals.</li><li>Replay the session and compare the reconstructed terminal buffer at specific timestamps against the known expected output.</li><li>Test time-scrub: scrub to 5 specific timestamps, verify the terminal state matches within 200ms render time.</li><li>Test missing snapshots: delete intermediate snapshots, replay, verify the engine degrades to event-only reconstruction with reduced fidelity.</li><li>Test corrupted snapshot: modify a snapshot&#39;s terminal buffer, replay, verify the engine falls back to the previous valid snapshot.</li><li>Test long session (1 hour simulated): verify replay does not run out of memory.</li><li>Test playback controls: verify play, pause, and speed changes work without skipping or repeating events.</li><li>Measure scrub-to-render latency for various session lengths and assert &lt; 200ms (p95).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/replay-fidelity.test.ts</code></li></ul></li><li>Acceptance: <ul><li>95%+ visual accuracy for test sessions.</li><li>Scrub-to-render &lt; 200ms (p95).</li><li>Missing/corrupted snapshots handled gracefully.</li><li>Long sessions handled without memory issues.</li></ul></li><li>Parallel: Yes (after T014-T016 are functional).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Chaos tests for zero event loss.</li><li>Retention compliance with known-timestamp events.</li><li>Deletion proof hash chain verification.</li><li>Export redaction scanning (1000 bundles).</li><li>Replay visual diff against known output.</li><li>Performance benchmarks for scrub-to-render.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Replay fidelity depends on snapshot interval.</li><li>Mitigation: Event-based interpolation between snapshots; document fidelity limitations.</li><li>Risk: Deletion proof hash chain computation is slow for large purge batches.</li><li>Mitigation: Batch hash computation; stream-based hashing.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm snapshots captured at configurable intervals.</li><li>Confirm replay handles missing/corrupted snapshots gracefully.</li><li>Confirm retention purge respects legal hold.</li><li>Confirm deletion proofs are verifiable.</li><li>Confirm export blocks without redaction rules.</li><li>Confirm chaos tests use real storage (not mocked).</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:36:09Z – claude-haiku – shell_pid=82027 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:37:26Z – claude-haiku – shell_pid=82027 – lane=done – Implemented: Session snapshots, replay engine, retention policies, deletion proofs, and secure export with redaction</li></ul>',36)])])}const m=t(l,[["render",a]]);export{h as __pageData,m as default};
